// Kontrollerar att startsidan anger teckenkodning tidigt och att Husbandets rubrik ryms på 320 px.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const html = fs.readFileSync('public/index.html', 'utf8');
const hb = fs.readFileSync('public/husbandet.js', 'utf8');
const pos = html.toLowerCase().indexOf('<meta charset="utf-8">');
const krav = {
  charsetFinns: pos > -1,
  charsetTidigt: pos > -1 && pos < 1024,
  charsetForeTitel: pos > -1 && pos < html.indexOf('<title>'),
  rubrikSkalar: /<h1 style="font-size:clamp\(\d+px,\s*\d+vw,\s*56px\)/.test(hb),
  ingenFast56: !/<h1 style="font-size:56px">/.test(hb),
};
const ok = Object.values(krav).every(Boolean);
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
